        for (int i = 2; i < n; i++) {
            long long c1 = 0, c2 = 0;
            for (int y : arr1) c1 += y > nums[i];
            for (int y : arr2) c2 += y > nums[i];
            bool to1 = c1 > c2 || (c1 == c2 && arr1.size() <= arr2.size());
            (to1 ? arr1 : arr2).push_back(nums[i]);
        }
        arr1.insert(arr1.end(), arr2.begin(), arr2.end());
        return arr1;
    }
};

