class Solution:
    def resultArray(self, nums):
        vals = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(vals)}
        m = len(vals)

        def make():
            return [0] * (m + 1)

        def add(t, i):
            while i <= m:
                t[i] += 1
                i += i & (-i)

        def pref(t, i):
            s = 0
            while i > 0:
                s += t[i]
                i -= i & (-i)
            return s

        t1, t2 = make(), make()
        add(t1, rank[nums[0]])
        add(t2, rank[nums[1]])
        arr1, arr2 = [nums[0]], [nums[1]]
        for x in nums[2:]:
            r = rank[x]
            c1 = len(arr1) - pref(t1, r)
            c2 = len(arr2) - pref(t2, r)
            if c1 > c2 or (c1 == c2 and len(arr1) <= len(arr2)):
                add(t1, r)
                arr1.append(x)
            else:
                add(t2, r)
                arr2.append(x)
        return arr1 + arr2

