class Solution {
    struct BIT {
        int n;
        vector<int> t;
        BIT(int n) : n(n), t(n + 1, 0) {}
        void add(int i) { for (; i <= n; i += i & -i) t[i]++; }
        int pref(int i) { int s = 0; for (; i > 0; i -= i & -i) s += t[i]; return s; }
    };
public:
    vector<int> resultArray(vector<int>& nums) {
        vector<int> vals = nums;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        auto rk = [&](int v) { return lower_bound(vals.begin(), vals.end(), v) - vals.begin() + 1; };
        int m = vals.size(), n = nums.size();
        BIT t1(m), t2(m);
        t1.add(rk(nums[0])); t2.add(rk(nums[1]));
        vector<int> arr1{nums[0]}, arr2{nums[1]};
        for (int i = 2; i < n; i++) {
            int r = rk(nums[i]);
            int c1 = arr1.size() - t1.pref(r);
            int c2 = arr2.size() - t2.pref(r);
            bool to1 = c1 > c2 || (c1 == c2 && arr1.size() <= arr2.size());
            if (to1) { t1.add(r); arr1.push_back(nums[i]); }
            else { t2.add(r); arr2.push_back(nums[i]); }
        }
        arr1.insert(arr1.end(), arr2.begin(), arr2.end());
        return arr1;
    }
};

