class Solution {
    static class BIT {
        int[] t;
        BIT(int n) { t = new int[n + 1]; }
        void add(int i) { for (; i < t.length; i += i & -i) t[i]++; }
        int pref(int i) { int s = 0; for (; i > 0; i -= i & -i) s += t[i]; return s; }
    }
    public int[] resultArray(int[] nums) {
        int[] vals = nums.clone();
        Arrays.sort(vals);
        int m = 0;
        for (int i = 0; i < vals.length; i++)
            if (i == 0 || vals[i] != vals[i - 1]) vals[m++] = vals[i];
        BIT t1 = new BIT(m), t2 = new BIT(m);
        List<Integer> a1 = new ArrayList<>(), a2 = new ArrayList<>();
        a1.add(nums[0]); a2.add(nums[1]);
        t1.add(rank(vals, m, nums[0])); t2.add(rank(vals, m, nums[1]));
        for (int i = 2; i < nums.length; i++) {
            int r = rank(vals, m, nums[i]);
            int c1 = a1.size() - t1.pref(r);
            int c2 = a2.size() - t2.pref(r);
            boolean to1 = c1 > c2 || (c1 == c2 && a1.size() <= a2.size());
            if (to1) { t1.add(r); a1.add(nums[i]); }
            else { t2.add(r); a2.add(nums[i]); }
        }
        int[] res = new int[nums.length];
        int k = 0;
        for (int x : a1) res[k++] = x;
        for (int x : a2) res[k++] = x;
        return res;
    }
    private int rank(int[] vals, int m, int v) {
        int lo = 0, hi = m - 1;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (vals[mid] < v) lo = mid + 1; else hi = mid; }
        return lo + 1;
    }
}

