class Solution {
    public int[] resultArray(int[] nums) {
        List<Integer> A = new ArrayList<>(), B = new ArrayList<>(), o1 = new ArrayList<>(), o2 = new ArrayList<>();
        A.add(nums[0]); B.add(nums[1]); o1.add(nums[0]); o2.add(nums[1]);
        for (int i = 2; i < nums.length; i++) {
            int c1 = A.size() - upperBound(A, nums[i]);
            int c2 = B.size() - upperBound(B, nums[i]);
            boolean to1 = c1 > c2 || (c1 == c2 && A.size() <= B.size());
            if (to1) { A.add(upperBound(A, nums[i]), nums[i]); o1.add(nums[i]); }
            else { B.add(upperBound(B, nums[i]), nums[i]); o2.add(nums[i]); }
        }
        o1.addAll(o2);
        int[] res = new int[nums.length];
        for (int i = 0; i < res.length; i++) res[i] = o1.get(i);
        return res;
    }
    private int upperBound(List<Integer> a, int v) {
        int lo = 0, hi = a.size();
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a.get(mid) <= v) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

